def is_valid_ipv4(text):
    """Says whether text is an IPv4 address.

    Four dot-separated decimal numbers from 0 to 255, no leading zeros.
    """
    parts = text.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not (part.isascii() and part.isdigit()):
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False
    return True

files.tests/test_netaddr.py:
from netaddr import is_valid_ipv4


def test_accepts_an_address():
    assert is_valid_ipv4("192.168.0.1") is True


def test_rejects_words():
    assert is_valid_ipv4("not.an.ip.address") is False


def test_accepts_zero_address():
    assert is_valid_ipv4("0.0.0.0") is True


def test_accepts_max_address():
    assert is_valid_ipv4("255.255.255.255") is True


def test_rejects_out_of_range():
    assert is_valid_ipv4("999.1.1.1") is False
    assert is_valid_ipv4("1.2.3.256") is False


def test_rejects_leading_zeros():
    assert is_valid_ipv4("01.2.3.4") is False


def test_rejects_wrong_part_count():
    assert is_valid_ipv4("1.2.3") is False
    assert is_valid_ipv4("1.2.3.4.5") is False


def test_rejects_negative_and_spaces():
    assert is_valid_ipv4("1.2.3.-4") is False
    assert is_valid_ipv4("1.2.3. 4") is False
    assert is_valid_ipv4("1.2.3.") is False
    assert is_valid_ipv4("") is False

